#' Build a Scout MRM method for SCIEX OS
#'
#' @description
#' Generate a Scout-triggered MRM acquisition method that can be directly copied
#' and pasted into SCIEX OS. Scout transitions are monitored first to trigger
#' acquisition of corresponding MRM transitions.
#'
#' @param Scout_Data_frame Data frame of detected Scout transitions.
#' @param Transi_MRM Data frame of ion-pair MRM transitions
#'        generated by \code{Generate_ions_pairs()}.
#' @param limitation_transi_group Maximum number of MRM transitions per RT group.
#' @param chooseSMRM Selection criteria for MRM transitions:
#'        \code{"max"} highest intensity,
#'        \code{"min"} lowest intensity,
#'        \code{"all"} include all transitions (default).
#' @param polarity Ion polarity for energy computation:
#'        \code{1} for positive, \code{0} for negative.
#' @param treshold_detection Scout detection threshold.
#' @param DP Declustering potential for Scout transitions.
#' @param CE Collision energy for Scout transitions
#'        (can be overwritten by CE_fonction).
#' @param CE_fonction Function for collision energy computation.
#' @param CXP Collision cell exit potential.
#' @param EP Entrance potential.
#' @param DW.Scout Dwell time for Scout transitions.
#'
#' @return A list of data frames. Each element corresponds
#'         to a separate MRM method file ready for SCIEX OS.
#' @export
Build_ScoutMRM_method <- function(
    Scout_Data_frame, Transi_MRM,
    limitation_transi_group = 200,
    chooseSMRM = c("max", "min", "all"),
    polarity = c(0),
    treshold_detection = 2000,
    DP = 100,
    CE = 10,
    CE_fonction = Calcul_CE_vector,
    CXP = 5,
    EP = 10,
    DW.Scout = 10
) {

  chooseSMRM <- match.arg(chooseSMRM)

  # Sort by retention time
  Transi_Scout <- Scout_Data_frame[order(Scout_Data_frame$rt.seconds), ]
  Transi_MRM <- Transi_MRM[order(Transi_MRM$rt.seconds), ]
  conversion <- ifelse(as.numeric(polarity) == 1, -1, 1)
  # Scout transitions table
  Methode_scout <- data.frame(
    groupeID = gsub("_\\d+$", "", Transi_Scout$Scout),
    CompoundID = Transi_Scout$Scout,
    trigger = TRUE,
    threshold.detection = treshold_detection,
    rt = Transi_Scout$rt.minutes,
    Q1 = Transi_Scout$mz.precursor,
    Q3 = Transi_Scout$mz.product,
    edit.DW = TRUE,
    DW = DW.Scout,
    DP = Transi_Scout$DP,
    EP = Transi_Scout$EP,
    CE = Transi_Scout$CE,
    CXP = Transi_Scout$CXP
  )

  # MRM transitions table (non triggering)
  Methode_autres_transitions <- data.frame(
    groupeID = Transi_MRM$Name,
    CompoundID = Transi_MRM$Name,
    trigger = FALSE,
    threshold.detection = 0,
    rt = Transi_MRM$rt.minutes,
    Q1 = Transi_MRM$mz.precursor,
    Q3 = Transi_MRM$mz.product,
    edit.DW = FALSE,
    DW = 0,
    DP = -100 * conversion,
    EP = -5 * conversion,
    CE = 0,
    CXP = -5 * conversion,
    Q1.intensity = Transi_MRM$Q1.intensity
  )

  Methode_autres_transitions <- CE_fonction(Methode_autres_transitions, conversion)

  # Remove Scouts from MRM list
  Methode_autres_transitions <- Methode_autres_transitions[
    !(Methode_autres_transitions$CompoundID %in% Transi_Scout$Name), ]

  Methode_autres_transitions <- Group_Compound_ID(Methode_autres_transitions)

  # Define retention time limits for grouping
  rt_bounds <- c(unique(Methode_scout$rt), max(Methode_autres_transitions$rt))
  lower_rt <- 0
  limit_b <- c()
  limit_h <- c()

  for (upper_rt in rt_bounds) {
    limit_b <- c(limit_b, max(1, ifelse(length(limit_h) == 0, 1, limit_h[length(limit_h)] + 1)))
    limit_h <- c(limit_h,
                 max(which(Methode_autres_transitions$rt > lower_rt & Methode_autres_transitions$rt <= upper_rt)))
    lower_rt <- upper_rt
  }

  # Build final method
  if (chooseSMRM == "all") {
    n_files <- ceiling((limit_h - limit_b) / limitation_transi_group)
    Methode_Scout_Final <- vector("list", length = max(n_files))

    for (i in seq_along(limit_b)) {
      trans_group <- Methode_autres_transitions[limit_b[i]:limit_h[i], ]
      trans_group <- Randomize_DataFrame_By_Group(trans_group)

      rows_per_part <- ceiling(nrow(trans_group) / max(n_files))

      for (j in seq_len(max(n_files))) {
        start_idx <- (j - 1) * rows_per_part + 1
        end_idx <- min(j * rows_per_part, nrow(trans_group))
        Methode_Scout_Final[[j]] <- rbind(Methode_Scout_Final[[j]],
                                          trans_group[start_idx:end_idx, ])
      }
    }

  } else {
    Methode_Scout_Final <- vector("list", length = 1)
    for (i in seq_along(limit_b)) {
      trans_group <- Methode_autres_transitions[limit_b[i]:limit_h[i], ]
      trans_group <- trans_group[order(trans_group$Q1.intensity, decreasing = (chooseSMRM == "max")), ]
      dim_limit <- min(nrow(trans_group), limitation_transi_group)
      Methode_Scout_Final[[1]] <- rbind(Methode_Scout_Final[[1]],
                                        trans_group[1:dim_limit, ])
    }
  }

  # Append Scout transitions
  Methode_Scout_Final <- lapply(
    Methode_Scout_Final,
    function(df) rbind(df[, 1:13], Methode_scout)
  )

  Methode_Scout_Final <- Sort_DataFrames_List(Methode_Scout_Final, order_column = "rt")
  return(Methode_Scout_Final)
}


#' Compute collision energy values based on precursor mass
#'
#' @param df_list Data frame of transitions.
#' @param conversion Polarity conversion factor.
#' @param slope Slope for the CE function.
#' @param intercept Intercept for the CE function.
#'
#' @return Updated data frame including CE values.
Calcul_CE_vector <- function(df_list, conversion,
                             slope = 0.05, intercept = 15) {
  for (j in 1:nrow(df_list)) {
    CE <- ifelse(abs(df_list[j, "Q1"] - df_list[j, "Q3"]) < 0.3,
                 5, slope * df_list[j, "Q1"] + intercept)
    df_list[j, "CE"] <- -CE * conversion
  }
  return(df_list)
}


#' Create unique CompoundID values inside each group
#'
#' @param df.transi Data frame of transitions.
#'
#' @return Data frame with formatted CompoundID values.
Group_Compound_ID <- function(df.transi) {
  df.transi$CompoundID <- ave(
    df.transi$groupeID, df.transi$groupeID,
    FUN = function(x) paste0(x, "_", seq_along(x))
  )
  return(df.transi)
}


#' Sort a list of data frames by a specified column
Sort_DataFrames_List <- function(df_list, order_column = "rt") {
  for (i in seq_along(df_list)) {
    df_list[[i]] <- df_list[[i]][order(df_list[[i]][[order_column]]), ]
  }
  return(df_list)
}


#' Randomize rows while preserving group structure
Randomize_DataFrame_By_Group <- function(df) {
  shuffled_groups <- sample(split(df, df[["groupeID"]]))
  return(do.call(rbind, shuffled_groups))
}
